/**
 * Black Rock City's house-music camps and art cars, with their SoundClouds, for the playa
 * game (playa.ts places them, PlayaWin.tsx draws them and plays them). Names and SoundCloud
 * links only: no logos, no pictures.
 *
 * Addresses are each camp's most recent published placement, from Burning Man's own camp
 * data as mirrored by iBurn (github.com/iBurnApp/iBurn-Data, data/<year>/APIData/…/camp.json),
 * converted to the game's "clock & street" form ("Esplanade & 8:00" → "8:00 & Esplanade",
 * a plaza like "9:00 G Plaza" → "9:00 & G"; older years' named streets by their letter, Gold → G).
 * Any year, any genre: the latest placement found, however old, and `approx` where there was
 * none. Art cars roam and have no address. Every
 * SoundCloud link answered SoundCloud's oEmbed on 2026-10-22 (soundcamps.test.mjs checks the
 * shape, not the network).
 *
 * `nudge` moves a camp along its street, in feet; playa.ts also slides any camp whose bay would
 * land on another's further along its street. No imports, no DOM.
 */

export type SoundCamp = {
  /** a stable key: "camp:<id>" / "mutant:<id>" in playa.ts */
  id: string;
  name: string;
  blurb: string;
  /** the camp's SoundCloud profile, or a set recorded at the camp */
  soundcloud: string;
  /** more sets to pick from in the parked panel */
  sets?: { url: string; title: string }[];
  /** "8:00 & Esplanade": the latest placement; none for an art car or the fence */
  address?: string;
  year?: number;
  /** placed plausibly, not from a published placement */
  approx?: boolean;
  /** a theme camp, an art car (mutant vehicle) that roams, the stage out at the trash fence, or a
   * place out on the open playa with its own music (an art piece, the Temple, an orchestra) */
  kind: "camp" | "mutant" | "fence" | "art";
  /** where an "art" place stands: its clock and its distance from the Man in real feet */
  playa?: { clock: string; ft: number };
  /** feet along the street from the default spot, to keep two camps on one corner apart */
  nudge?: number;
};

